  "d.109szp9": "ಢಿಕ್ಕಿ ಹೊಡೆಯಬಹುದಾದ ಘನ ಭೂಪ್ರದೇಶ ಅಥವಾ ರಚನೆಗಳು.",
  "d.10azxrl": "ದ್ಯುತಿಗೋಳದಿಂದ ಮೂರು ಸೌರ ತ್ರಿಜ್ಯಗಳ ಎತ್ತರ. ನೆರಳೇ ಜೀವ: ವೇದಿಕೆಯ ಕವಚ, ಧೂಮಕೇತು, ದೊಡ್ಡ ಹಲ್‌ಗಳು. ಜ್ವಾಲೆಗಳು ಕೆಲವು ನಿಮಿಷಗಳಿಗೊಮ್ಮೆ ಬರುತ್ತವೆ.",
  "d.10wlatv": "ಅತಿ ಪ್ರಕಾಶಮಾನ ಚಾನೆಲ್ 0x40 ಕ್ಕಿಂತ ಕಡಿಮೆ ಇರುವ ಕಸ್ಟಮ್ ಬಣ್ಣವನ್ನು STOCK ಎಂದು ಓದಲಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಕವಚ ಎಂದಿಗೂ ಅದೃಶ್ಯವಾಗುವುದಿಲ್ಲ.",
  "d.11cuwtu": "ರಾಕೆಟ್‌ಗಳು",
  "d.11jyj1n": "ಮಧ್ಯಮ ಬೆನ್ನೆಲುಬಿನ ರೈಲ್‌ಗನ್ ಸುತ್ತ ನಿರ್ಮಿಸಿದ ವಿಧ್ವಂಸಕ ನೌಕೆ; ಲೇಸರ್ ಗೋಪುರಗಳು ಮತ್ತು ಹದಿನಾರು ರಾಕೆಟ್ ಕೋಶಗಳು ಇದರಲ್ಲಿವೆ.",
  "d.11phsqq": "100% AI ರಚಿತ ವಿಷಯವನ್ನು ಅನುಮತಿಸುವ ಆಟದ ಪ್ರಕಾಶಕರು ಆಟವನ್ನು ಪ್ರಕಟಿಸುತ್ತಾರೆ.",
  "d.11zjijr": "ಶಸ್ತ್ರಾಸ್ತ್ರಗಳನ್ನು ನಿಯೋಜಿಸಬಹುದು ಮತ್ತು ಹಿಂತೆಗೆಯಬಹುದು (ಹಿಂತೆಗೆದ ಶಸ್ತ್ರಾಸ್ತ್ರಗಳು ಮರೆಯಾಗುತ್ತವೆ), ಮತ್ತು ನೌಕೆಗಳು ಇನ್ನು ಹೊಗೆಯ ಜಾಡು ಬಿಡುವುದಿಲ್ಲ.",
  "d.11zq7hg": "ನೋಟ: ಭೌತಿಕವಾಗಿ ಬೆಳಗಿದ ಕಾಕ್‌ಪಿಟ್‌ಗಳು, ವರ್ಗೀಕೃತ ನಕ್ಷತ್ರಗಳು, ಉಂಗುರಗಳಿರುವ ಅನಿಲ ದೈತ್ಯ ಗ್ರಹ, ಗೆಲಾಕ್ಸಿ ಮತ್ತು ನೀಹಾರಿಕೆಯ ಹಿನ್ನೆಲೆ, ಎಂಜಿನ್ ಜ್ವಾಲೆಗಳು ಮತ್ತು ಸಂಚರಣೆ ದೀಪಗಳು; 0.1.0 ರ ಆಟದ ಅನುಭವ ಸ್ಥಿರಗೊಳಿಸಲಾಗಿದೆ.",
  "d.12zyt91": "ANVIL, ಆಟದ ಮೆನುವಿನ ಹ್ಯಾಂಗರ್ ಚಿತ್ರ (0.3.0 ಮತ್ತು ನಂತರದ ಆವೃತ್ತಿಗಳಿಗಾಗಿ ನಿರ್ಮಿಸಿದ ಹಲ್; ಮೂಲ ಗಾತ್ರ 256 x 128). ಆಟದ ಕ್ಯಾಪ್ಚರ್, ಆವೃತ್ತಿ 0.6.1",
  "d.13cb0px": "ನಗರದ ಮೇಲೆ ಶತ್ರುಗಳು, ಎಂಜಿನ್ ಜ್ವಾಲೆಗಳೊಂದಿಗೆ (GLASGOW). ಆಟದ ಕ್ಯಾಪ್ಚರ್, ಆವೃತ್ತಿ 0.5.3",
  "d.1436q76": "ಆವೃತ್ತಿ 0.5.1 ಸ್ಥಿರೀಕೃತ: ಹಾರ್ಡ್‌ಪಾಯಿಂಟ್ ಆಸನಗಳು, ಆರು-ರಾಕೆಟ್ ಸರಣಿ ಉಡಾವಣೆಗಳು, ಮತ್ತು 10 NEEDLE ನೌಕೆಗಳನ್ನು ಉಡಾಯಿಸುವ ANVIL ಬೇ.",
  "d.14s5uo6": "ಮುಖ್ಯ ಯುದ್ಧನೌಕೆ ಮತ್ತು ಯುದ್ಧವಿಮಾನದ ಮೇಲೆ ಎಂಜಿನ್ ಜ್ವಾಲೆಗಳು. ಆಟದ ಕ್ಯಾಪ್ಚರ್, ಆವೃತ್ತಿ 0.5.3",
  "d.14vqvyw": "ಹ್ಯಾಂಗರ್ ಬೇ ತೆರೆದಿರುವ ANVIL. ಆಟದ ಕ್ಯಾಪ್ಚರ್, ಆವೃತ್ತಿ 0.6.1",
  "d.14zbb1f": "THETA-7 ಕ್ಷುದ್ರಗ್ರಹ ಕ್ಷೇತ್ರದಲ್ಲಿ ಶತ್ರು ತಂಡದ ಗುಂಡಿನ ದಾಳಿಗೆ ಒಳಗಾದ ಸಣ್ಣ ಯುದ್ಧವಿಮಾನ, ಅದರ ಕವಚದ ಗುಳ್ಳೆ ಹೊಳೆಯುತ್ತಿದೆ.",
  "d.15oh132": "ಸ್ಥಿರೀಕೃತ ಆವೃತ್ತಿಗಳು",
  "d.16dme8w": "ಸ್ಥಿರ ಲೇಸರ್‌ಗಳು ನೌಕೆಯ ಮುಂದಿರುವ ಒಂದೇ ಗುರಿ ಬಿಂದುವಿಗೆ ಒಮ್ಮುಖವಾಗುತ್ತವೆ.",
  "d.16sui9e": "ನಗರದಷ್ಟು ದೊಡ್ಡ ಪ್ರಮುಖ ನೌಕೆ; ತಿರುಗುವ ವಾಸಸ್ಥಾನ ಡ್ರಮ್, ಎರಡು ಭಾರೀ ಬೆನ್ನೆಲುಬಿನ ರೈಲ್‌ಗಳು ಮತ್ತು ಗನ್‌ಗಳ ಕಾಡೇ ಇದರಲ್ಲಿದೆ.",
  "d.177y6xj": "ಡಬಲ್ ಬೂಸ್ಟ್.",
  "d.178olkv": "ಹ್ಯಾಂಗರ್ ಬೇ ಬಾಗಿಲು ತೆರೆದು ಬೆಳಕು ಹೊರಚೆಲ್ಲುತ್ತಿರುವ ANVIL ವಿಧ್ವಂಸಕ ನೌಕೆ.",
