  "d.18qbnrf": "AI ರಚಿತ ಟ್ರೇಲರ್ ಅನ್ನು AI ರಚಿತ ಕಲಾಕೃತಿಗಳ ಜೊತೆಗೆ ತಯಾರಿಸಲಾಗುತ್ತದೆ.",
  "d.18qvzf2": "NEEDLE, ಆಟದ ಮೆನುವಿನ ಹ್ಯಾಂಗರ್ ಚಿತ್ರ (0.3.0 ಮತ್ತು ನಂತರದ ಆವೃತ್ತಿಗಳಿಗಾಗಿ ನಿರ್ಮಿಸಿದ ಹಲ್; ಮೂಲ ಗಾತ್ರ 256 x 128). ಆಟದ ಕ್ಯಾಪ್ಚರ್, ಆವೃತ್ತಿ 0.6.1",
  "d.18yyc5": "ಮಾಡ್ಯೂಲ್‌ಗಳು ಪ್ರತ್ಯೇಕವಾಗಿ ಹಾನಿಗೊಳ್ಳುತ್ತವೆ ಮತ್ತು ಹಲ್ ಒಡೆದುಹೋಗುತ್ತದೆ.",
  "d.194nnt6": "ಫಾಯಿಲ್ ಸುತ್ತಿದ ಟ್ಯಾಂಕ್‌ಗಳು, ಸೆನ್ಸರ್ ಕಂಬ ಮತ್ತು ಅತಿದೊಡ್ಡ ಬೂಸ್ಟ್ ಸಂಗ್ರಹ ಹೊಂದಿರುವ ಉದ್ದ ಕಾಲಿನ ಸಮೀಕ್ಷಾ ನೌಕೆ.",
  "d.198svbo": "ಆವೃತ್ತಿ 0.5.0 ಸ್ಥಿರೀಕೃತ: ಭೌತಿಕವಾಗಿ ಬೆಳಗಿದ ಕಾಕ್‌ಪಿಟ್‌ಗಳು, ವರ್ಗೀಕೃತ ನಕ್ಷತ್ರಗಳು, ಉಂಗುರಗಳಿರುವ ಅನಿಲ ದೈತ್ಯ ಗ್ರಹ ಮತ್ತು ನೀಹಾರಿಕೆಯ ಹಿನ್ನೆಲೆ.",
  "d.19i63zk": "ಆಟದ ಹ್ಯಾಂಗರ್ ಮೆನುವಿನಲ್ಲಿ ತೋರಿಸಿರುವ ORION-1, ಆವೃತ್ತಿ 0.6.1 ರ ಹಲ್, ಕಪ್ಪು ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಮುಕ್ಕಾಲು ಕೋನದ ನೋಟ.",
  "d.19mf6u": "MERIDIAN, ಆಟದ ಮೆನುವಿನ ಹ್ಯಾಂಗರ್ ಚಿತ್ರ (0.3.0 ಮತ್ತು ನಂತರದ ಆವೃತ್ತಿಗಳಿಗಾಗಿ ನಿರ್ಮಿಸಿದ ಹಲ್; ಮೂಲ ಗಾತ್ರ 256 x 128). ಆಟದ ಕ್ಯಾಪ್ಚರ್, ಆವೃತ್ತಿ 0.6.1",
