  "d.1bk3qbs": "24 km ಗುಣಿಸು 24 km ಪೆಟ್ಟಿಗೆ ಆಕಾರದ ಅಂಗಣ, ಮೃದು ಮೇಲ್ಛಾವಣಿ 9 km.",
  "d.1bkjp1s": "ಆವೃತ್ತಿ 0.2.3 ಸ್ಥಿರೀಕೃತ: ನಿಯೋಜಿಸಬಹುದಾದ ಮತ್ತು ಹಿಂತೆಗೆಯಬಹುದಾದ ಶಸ್ತ್ರಾಸ್ತ್ರಗಳು.",
  "d.1bt06ve": "ಬೆನ್ನೆಲುಬಿನ ರೈಲ್‌ಗನ್: ಚಾರ್ಜ್ ಮಾಡಲು ಹಿಡಿದುಕೊಳ್ಳಿ, ಹಾರಿಸಲು ಬಿಡಿ.",
