  "d.1c7mz24": "16 km ಗುಣಿಸು 12 km ಪೆಟ್ಟಿಗೆ ಆಕಾರದ ಅಂಗಣ, ಮೃದು ಮೇಲ್ಛಾವಣಿ 2.7 km.",
  "d.1c9et86": "ಆವೃತ್ತಿ 0.5.2 ಸ್ಥಿರೀಕೃತ: ಸ್ಕ್ವಾಡ್ರನ್ ನಿಲುವುಗಳು, ROCKETS INCOMING ಸೂಚನೆ ಮತ್ತು ಗೋಪುರ ಆಸನಗಳು.",
  "d.1czllhs": "ಕ್ರೂಸರ್",
  "d.1dlvg7e": "ಹಗುರ ಯುದ್ಧವಿಮಾನ",
  "d.1dlyq4f": "ರಾತ್ರಿ ಬದಿಯ ಮೇಲೆ 420 km ಎತ್ತರ, ಕಕ್ಷೀಯ ಸೂರ್ಯೋದಯಕ್ಕೆ ಮೂರು ನಿಮಿಷ ಮೊದಲು. Ashgrove Station, ಹಳೆಯ ಒಡೆತದ ಅವಶೇಷಗಳು, ಮತ್ತು ಕೆಳಗೆ ಜಾರುತ್ತಿರುವ ಯುರೋಪಿನ ದೀಪಗಳು.",
  "d.1dmfq0q": "ಟೂಲ್‌ಚೈನ್ ಮೂಲಕ ಆಟಕ್ಕೆ ಜೋಡಿಸಲಾಗಿದೆ",
  "d.1e2mh2n": "Unreal Engine 5 ಗೆ ಸ್ಥಳಾಂತರಿಸುವುದು ಸಂಪೂರ್ಣ ಮರುಬರವಣಿಗೆ.",
  "d.1e63f23": "ಗಾಳಿಯ ಪ್ರತಿರೋಧ ಅನ್ವಯಿಸುತ್ತದೆ.",
  "d.1ea9win": "ರಕ್ಷಾಕವಚವನ್ನು ಬಿಟ್ಟು ಬೃಹತ್ ಚಾಲನಾ ವಿಭಾಗ ಮತ್ತು ಎರಡು ಭಾರೀ ಬೆನ್ನೆಲುಬಿನ ರೈಲ್‌ಗಳನ್ನು ಆರಿಸಿಕೊಂಡ ಯುದ್ಧ ಕ್ರೂಸರ್.",
  "d.1eoopdx": "ಲಾಕ್-ಆನ್ ರಾಕೆಟ್‌ಗಳು: ರಾಕೆಟ್ ಉಡಾವಣೆಯಾಗುವಾಗ ಅದರ ಲಾಕ್ ಪೂರ್ಣವಾಗಿದ್ದರೆ ಮಾತ್ರ ಅದು ಮಾರ್ಗದರ್ಶಿತವಾಗುತ್ತದೆ.",
  "d.1eytq94": "ಬಿಡುಗಡೆ 0.3.0 ಎಲ್ಲಾ 16 ನೌಕೆ ವರ್ಗಗಳಿಗೆ ಹೊಸ ಹಲ್‌ಗಳನ್ನು ನೀಡುತ್ತದೆ (ದೃಶ್ಯ ಮಾತ್ರ: ಹೆಸರುಗಳು, ಪಾತ್ರಗಳು, ಅಂಕಿಅಂಶಗಳು ಮತ್ತು ಹಾರ್ಡ್‌ಪಾಯಿಂಟ್ ವಿನ್ಯಾಸಗಳು ಹಾಗೆಯೇ ಮುಂದುವರಿಯುತ್ತವೆ).",
  "d.1f5e5lj": "ವಾಹಕ ನೌಕೆ",
  "d.1fslkx6": "ANVIL ತನ್ನ ಹ್ಯಾಂಗರ್ ಬೇಯಿಂದ ಹತ್ತು ಮಿತ್ರ NEEDLE ನೌಕೆಗಳನ್ನು ಉಡಾಯಿಸುತ್ತದೆ.",
