  "d.svcsep": "ಗುರುತ್ವ 1.62 m/s2 (0.165 g).",
  "d.taax41": "Orion-81 ಲೋಗೋ: ದುಂಡಾದ ಬೆಳ್ಳಿ ಚೌಕಟ್ಟಿನೊಳಗೆ ಹೊಳೆಯುವ ಮೂರು ನೀಲಿ-ಬಿಳಿ ನಕ್ಷತ್ರಗಳು.",
  "d.tbfe8v": "ಮಾದರಿಗಳನ್ನು ಸಂಗ್ರಹಿಸಲಾಗಿದೆ, ಕಲಾ ಪುಸ್ತಕಗಳನ್ನು ರಚಿಸಲಾಗಿದೆ.",
  "d.tg0hgk": "THETA-7 ಕ್ಷುದ್ರಗ್ರಹ ಕ್ಷೇತ್ರದ ಉಂಗುರಗಳಿರುವ ಮತ್ತು ಕುಳಿಗಳಿರುವ ಬಂಡೆಗಳು.",
  "d.tg8bac": "ಆಟದ ಹ್ಯಾಂಗರ್ ಮೆನುವಿನಲ್ಲಿ ತೋರಿಸಿರುವ MERIDIAN, ಆವೃತ್ತಿ 0.6.1 ರ ಹಲ್, ಕಪ್ಪು ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಮುಕ್ಕಾಲು ಕೋನದ ನೋಟ.",
  "d.tg8pdz": "ಇದು 8 ಕವಚ ಬಣ್ಣಗಳನ್ನು, ಜೊತೆಗೆ ಒಂದು ಕಸ್ಟಮ್ ಬಣ್ಣವನ್ನು ನೀಡುತ್ತದೆ.",
  "d.th2bvi": "ವಿಭಾಗಗಳು, ಕ್ರಮವಾಗಿ: L1, ವರ್ಗ ಐಡಿ, ಹಲ್ ಅಂಕೆ + ಕವಚ ಅಂಕೆ, ಬಣ್ಣ, ಹಾರ್ಡ್‌ಪಾಯಿಂಟ್ ಟೋಕನ್‌ಗಳು, ನೌಕೆ ಐಡಿ, ನೌಕೆಯ ಹಲ್ ಅಂಕೆ + ನೌಕೆಯ ಕವಚ ಅಂಕೆ, ನೌಕೆಯ ಹಾರ್ಡ್‌ಪಾಯಿಂಟ್ ಟೋಕನ್‌ಗಳು. ಬಣ್ಣವು STOCK ಗೆ '-', ಪ್ಯಾಲೆಟ್ ನಮೂದು k ಗೆ 'p<k>', ಅಥವಾ ಆರು ಸಣ್ಣ ಅಕ್ಷರದ ಹೆಕ್ಸ್ ಅಂಕೆಗಳು. ವಿಭಾಗವು '00' (ಹಂತಗಳು), '-' (ಬಣ್ಣ, ನೌಕೆ) ಅಥವಾ ಖಾಲಿ (ಹಾರ್ಡ್‌ಪಾಯಿಂಟ್‌ಗಳು) ಆಗಿದ್ದರೆ ಅದು ಡೀಫಾಲ್ಟ್; ಕೊನೆಯ ಡೀಫಾಲ್ಟ್ ಅಲ್ಲದ ವಿಭಾಗದ ನಂತರದ ಪ್ರತಿ ಡೀಫಾಲ್ಟ್ ವಿಭಾಗವನ್ನು ಕೈಬಿಡಲಾಗುತ್ತದೆ, ಮೊದಲಿನವುಗಳನ್ನು ಉಳಿಸಲಾಗುತ್ತದೆ. ನೌಕೆಯ ವಿಭಾಗಗಳು ಹ್ಯಾಂಗರ್ ಬೇ ಇರುವ ವರ್ಗಕ್ಕೆ ಮಾತ್ರ ಇರುತ್ತವೆ. ವರ್ಗ ತೆಗೆದುಕೊಳ್ಳಲಾಗದ ಆಯ್ಕೆಯನ್ನು STOCK ಎಂದು ಓದಲಾಗುತ್ತದೆ.",
