  "faq.prototypeWasBuilt": "ಮೂಲಮಾದರಿಯನ್ನು ಮುಕ್ತ-ಮೂಲ Quake III Arena ಎಂಜಿನ್ (GPL) ಮೇಲೆ ನಿರ್ಮಿಸಲಾಯಿತು ಮತ್ತು Elite Dangerous ನೌಕೆಗಳನ್ನು ಸ್ಫೂರ್ತಿಯಾಗಿ ತೆಗೆದುಕೊಳ್ಳಲಾಯಿತು. ಎರಡನೇ ದಿನ ಆಟದ ಕೋಡ್ Claude Code ಬಳಸಿ ಬರೆದ ಹೊಸ ಎಂಜಿನ್ BuB ಗೆ ಸ್ಥಳಾಂತರಗೊಂಡಿತು; ಆಟದ ಮಾಡ್ಯೂಲ್‌ಗಳು ಮೂಲಮಾದರಿಯಿಂದ ಬಂದು ಮರುನಾಮಕರಣಗೊಂಡವು. ಬಿಡುಗಡೆ 0.3.0 ಎಲ್ಲಾ 16 ನೌಕೆ ವರ್ಗಗಳಿಗೆ ಹೊಸ ಹಲ್‌ಗಳನ್ನು ನೀಡಿತು. ಕೋಡ್‌ನ ಯಾವುದಾದರೂ ಭಾಗ ಇನ್ನೂ GPL ಮೂಲದಿಂದ ಪಡೆದದ್ದೇ ಎಂದು ಮತ್ತು ಆರಂಭಿಕ ನೌಕೆ ವಿನ್ಯಾಸಗಳು ತಮ್ಮ ಸ್ಫೂರ್ತಿಗೆ ತೀರಾ ಹತ್ತಿರವಾಗಿವೆಯೇ ಎಂದು ಪರವಾನಗಿ-ಅನುಸರಣೆ ಪರಿಶೀಲನೆ ಪರೀಕ್ಷಿಸುತ್ತಿದೆ. GPL ಮೂಲಮಾದರಿಯ ಮೂಲ ಕೋಡ್ ವಿರುದ್ಧ ಕೋಡ್‌ನ ಸ್ವಯಂಚಾಲಿತ ಹೋಲಿಕೆ ಸ್ಕ್ಯಾನ್ ಅನ್ನು <0/> ರಂದು ನಡೆಸಲಾಯಿತು, ಮತ್ತು ಅದರ ಹೊಂದಾಣಿಕೆಗಳ ಬಗ್ಗೆ ತಜ್ಞರ ಪರಿಶೀಲನೆ ನಡೆಯುತ್ತಿದೆ. ಪಡೆದದ್ದು ಎಂದು ಕಂಡುಬಂದ ಎಲ್ಲವನ್ನೂ ಮರುಬರೆಯಲಾಗುವುದು ಅಥವಾ ಮರುವಿನ್ಯಾಸ ಮಾಡಲಾಗುವುದು. ಪರಿಶೀಲನೆ ಮುಗಿಯುವವರೆಗೆ, ಉತ್ತರ ‘ಇಲ್ಲ’ ಎಂದು ನಾವು ಹೇಳಿಕೊಳ್ಳುವುದಿಲ್ಲ.",
  "faq.questions": "ಪ್ರಶ್ನೆಗಳು",
  "faq.shipsArtInterface": "ಆದಾಯ ಅನುಮತಿಸಿದಂತೆ ನೌಕೆಗಳು, ಕಲೆ, ಇಂಟರ್ಫೇಸ್ ಮತ್ತು ಇನ್ನಷ್ಟು. <0>ಈ ಪುಟದ ಲೆಕ್ಕಪತ್ರ<\/0> ಪ್ರತಿ ಅಂಶವನ್ನು ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ ಮತ್ತು ಪ್ರತಿ ಬದಲಿಯನ್ನು ಹಾಗೂ ಅದರ ವಿನ್ಯಾಸಕರನ್ನು ತೋರಿಸುತ್ತದೆ.",
  "faq.shipsUpgradesPlanned": "ನೌಕೆಗಳು ಮತ್ತು ಉನ್ನತೀಕರಣಗಳನ್ನು ಆಡಿ ಗಳಿಸಬಹುದಾದಂತೆ ಅಥವಾ ಖರೀದಿಸಬಹುದಾದಂತೆ ಯೋಜಿಸಲಾಗಿದೆ. ಆಟಗಾರ-ವಿರುದ್ಧ-ಆಟಗಾರ ಪಂದ್ಯಗಳಲ್ಲಿ ಹಣ ನೀಡಿ ಪಡೆದ ನೌಕೆಗಳು ನ್ಯಾಯಯುತವಾಗಿ ಹೇಗೆ ಉಳಿಯುತ್ತವೆ ಎಂಬುದನ್ನು ಇನ್ನೂ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗುತ್ತಿದೆ.",
  "faq.thatPlanFree": "ಅದೇ ಯೋಜನೆ: ಐಚ್ಛಿಕ ಆಟದೊಳಗಿನ ಕರೆನ್ಸಿ ಮತ್ತು ಅಲಂಕಾರಗಳೊಂದಿಗೆ ಆಡಲು ಉಚಿತ. ಇದನ್ನು ಇನ್ನೂ ನಿರ್ಮಿಸಿಲ್ಲ.",
  "faq.wasAnyoneS": "ಯಾರದ್ದಾದರೂ ಕೆಲಸವನ್ನು ನಕಲು ಮಾಡಲಾಗಿದೆಯೇ?",
  "faq.whenOutWhat": "ಇದು ಯಾವಾಗ ಬರುತ್ತದೆ, ಮತ್ತು ಯಾವುದರಲ್ಲಿ?",
  "faq.whichPartsWill": "ಯಾವ ಭಾಗಗಳನ್ನು ಜನರು ಬದಲಾಯಿಸುತ್ತಾರೆ, ಮತ್ತು ನನಗೆ ಹೇಗೆ ತಿಳಿಯುತ್ತದೆ?",
  "faq.whyWouldAi": "AI-ನಿರ್ಮಿತ ಆಟ ವಿನ್ಯಾಸಕರಿಗೆ ಹೇಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ?",
  "faq.willPayWin": "ಇದು ಹಣ ಕೊಟ್ಟು ಗೆಲ್ಲುವ ಆಟವಾಗುತ್ತದೆಯೇ?",
  "faq.windowsPcThere": "Windows PC. ಇನ್ನೂ ಬಿಡುಗಡೆ ದಿನಾಂಕ ಅಥವಾ ಬೆಲೆ ಇಲ್ಲ.",
  "footer.anthropicClaudeClaude": "Anthropic, Claude ಮತ್ತು Claude Code ಇವು Anthropic, PBC ಯ ಟ್ರೇಡ್‌ಮಾರ್ಕ್‌ಗಳು. Unreal Engine ಮತ್ತು Epic Games ಇವು Epic Games, Inc. ನ ಟ್ರೇಡ್‌ಮಾರ್ಕ್‌ಗಳು. Blender ಇದು Blender Foundation ನ ಟ್ರೇಡ್‌ಮಾರ್ಕ್. Quake III Arena ಮತ್ತು Elite Dangerous ಇವು ಆಯಾ ಮಾಲೀಕರ ಟ್ರೇಡ್‌ಮಾರ್ಕ್‌ಗಳು. ಎಲ್ಲಾ ಹೆಸರುಗಳು ಅವುಗಳ ಮಾಲೀಕರಿಗೆ ಸೇರಿವೆ ಮತ್ತು ಉಲ್ಲೇಖಿಸಿದ ಉತ್ಪನ್ನಗಳನ್ನು ಗುರುತಿಸಲು ಮಾತ್ರ ಬಳಸಲಾಗಿದೆ. Orion-81 ಅವುಗಳಲ್ಲಿ ಯಾವುದರೊಂದಿಗೂ ಸಂಯೋಜಿತವಾಗಿಲ್ಲ, ಪ್ರಾಯೋಜಿತವಾಗಿಲ್ಲ ಅಥವಾ ಅನುಮೋದಿತವಾಗಿಲ್ಲ.",
  "footer.aspirationalNoPartnership": "ಇದು ಕೇವಲ ಆಶಯ. ಯಾವುದೇ ಪಾಲುದಾರಿಕೆ, ಸಂಯೋಜನೆ ಅಥವಾ ಅನುಮೋದನೆ ಅಸ್ತಿತ್ವದಲ್ಲಿಲ್ಲ.",
