  "proof.pipeAria": "ಕೆಲಸದ ಪೈಪ್‌ಲೈನ್, ಒಂಬತ್ತು ಹಂತಗಳು. ಒಂದು ಸಾಲಿನ ವಿವರಣೆಗಾಗಿ ಪ್ರತಿ ಹಂತವನ್ನು ಆರಿಸಬಹುದು.",
  "proof.showSources": "ಆಕರಗಳನ್ನು ತೋರಿಸಿ",
  "proof.since202610": "2026-10-03 ರಿಂದ (ಆವೃತ್ತಿ 0.2.1 ರಿಂದ ಮುಂದೆ), ಯೋಜಕ ಮಾದರಿ (Claude Opus 5.5) ಯೋಜನೆ ಮತ್ತು ಒಪ್ಪಿಗೆ ಮಾನದಂಡಗಳನ್ನು ಟ್ರ್ಯಾಕರ್‌ನಲ್ಲಿ ಬರೆಯುತ್ತದೆ. ಕಾರ್ಯಗತಕಾರ ಮಾದರಿಗಳು (Claude Sonnet 5.5) ಸಮಾನಾಂತರವಾಗಿ ನಿರ್ಮಿಸುತ್ತವೆ, ಪ್ರತಿಯೊಂದೂ ತನ್ನದೇ ಫೈಲ್‌ಗಳ ಮೇಲೆ. ಯೋಜಕ ಪರಿಶೀಲಿಸುತ್ತದೆ, ಕಾರ್ಯಗತಕಾರರು ಸರಿಪಡಿಸುತ್ತಾರೆ, ಪರಿಶೀಲನೆಗಳು ನಡೆಯುತ್ತವೆ, ಮತ್ತು ಆಮೇಲೆ ಮಾತ್ರ ಆವೃತ್ತಿಯನ್ನು ಸ್ಥಿರೀಕರಿಸಲಾಗುತ್ತದೆ. ಹಿಂದಿನ ಆವೃತ್ತಿಗಳನ್ನು (v0 ರಿಂದ 0.2.0) Claude Code ಒಂದೇ ಮಾದರಿಯೊಂದಿಗೆ ಯೋಜಿಸಿ ನಿರ್ಮಿಸಿತು.",
  "proof.testChecksOne": "ಪರೀಕ್ಷಾ ಪರಿಶೀಲನೆಗಳು: ಎಂಜಿನ್ ಪರೀಕ್ಷೆಯಲ್ಲಿನ ಒಂದು ಸಮಯ ಪರಿಶೀಲನೆ (0.6 ms ಮಿತಿಗೆ ಎದುರಾಗಿ 0.606 ms) ವಿಫಲವಾಯಿತು ಮತ್ತು ಅದನ್ನು ಮನ್ನಾ ಮಾಡಲಾಯಿತು (ORI-0948); ಉಳಿದ ಪ್ರತಿ ಸೂಟ್ 0 ವೈಫಲ್ಯಗಳನ್ನು ವರದಿ ಮಾಡಿತು.",
