  "why.anthropic": "Anthropic ಗಾಗಿ",
  "why.anthropicSEconomic": "<0>Anthropic ನ ಆರ್ಥಿಕ ಸೂಚ್ಯಂಕ (<1/>)<\/0> ವೃತ್ತಿಜೀವನದ ಆರಂಭದ ಕೆಲಸಗಾರರು ತಮ್ಮ ಕೆಲಸದ ಹೆಚ್ಚಿನ ಭಾಗವನ್ನು AI ಯಿಂದ ಮಾಡಬಹುದಾದದ್ದು ಎಂದು ಕಾಣುತ್ತಾರೆ ಎಂದು ಕಂಡುಕೊಂಡಿದೆ.",
  "why.anthropicSEconomic2": "<0>Anthropic ನ ಆರ್ಥಿಕ ನೀತಿ ಚೌಕಟ್ಟು (<1/>)<\/0> ಸಂಸ್ಥೆಗಳು ಜನರನ್ನು ಕೈಬಿಡುವ ಬದಲು ಮರುತರಬೇತಿ ನೀಡಿ ಮರುನಿಯೋಜಿಸಬೇಕೆಂದು ಕೇಳುತ್ತದೆ.",
  "why.anthropicSReview": "<0>Anthropic ನ ಮರುತರಬೇತಿ ಸಾಕ್ಷ್ಯದ ವಿಮರ್ಶೆ (<1/>)<\/0> ಉದ್ಯೋಗದಾತರೊಂದಿಗೆ ಜೋಡಿತ, ವಲಯ-ನಿರ್ದಿಷ್ಟ ಕಾರ್ಯಕ್ರಮಗಳು ಅತ್ಯುತ್ತಮವಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತವೆ ಎಂದು ಕಂಡುಕೊಂಡಿದೆ.",
  "why.askSimpleFive": "ಕೋರಿಕೆ ಸರಳ: ಆರಂಭಿಸಲು ಐದು Claude ಸೀಟ್‌ಗಳು. ಸ್ಥಾಪಕರು ಅವನ್ನು ಪ್ರತಿಭಾವಂತ, ಉತ್ಸಾಹಿ ಜನರಿಂದ ತುಂಬಲು ಸಾಧ್ಯವಾದರೆ, AI ಅನ್ನು ಒಳ್ಳೆಯ ಉದ್ದೇಶದಿಂದ ಬಳಸಿ ಸುಂದರವಾದದ್ದನ್ನು ಹೇಗೆ ಮಾಡಬಹುದು ಎಂದು ನಾವು ತೋರಿಸುತ್ತೇವೆ.",
  "why.context": "ಹಿನ್ನೆಲೆ",
  "why.designersEngineers": "ವಿನ್ಯಾಸಕರು ಮತ್ತು ಎಂಜಿನಿಯರ್‌ಗಳಿಗಾಗಿ",
  "why.everyItemBelow": "ಕೆಳಗಿನ ಪ್ರತಿ ಅಂಶವೂ ಯೋಜನೆ ಅಥವಾ ಇನ್ನೂ ಘೋಷಿಸಬೇಕಾದದ್ದು. ಇಲ್ಲಿ ಯಾವುದನ್ನೂ ಒಪ್ಪಿಕೊಂಡಿಲ್ಲ, ಮತ್ತು ಯಾವುದೇ ಮೊತ್ತದ ಭರವಸೆ ನೀಡಿಲ್ಲ.",
  "why.founderWentFrom": "ಒಬ್ಬ ಸ್ಥಾಪಕರು ಮೂಲಮಾದರಿಯಿಂದ 0.6.1 ವರೆಗೆ <0/> ದಿನಗಳಲ್ಲಿ ತಲುಪಿದರು. ಐದು ಜನರ ಸಮರ್ಪಿತ ತಂಡ ಏನು ಮಾಡಬಹುದು ಎಂದು ಊಹಿಸಿ.",
  "why.fromAnthropic": "Anthropic ನಿಂದ",
  "why.fromBackers": "ಬೆಂಬಲಿಗರಿಂದ",
  "why.fullyDisclosedAi": "ಆಟಗಾರರು ಪರಿಶೀಲಿಸಬಹುದಾದ ಧ್ಯೇಯವಿರುವ, ಸಂಪೂರ್ಣವಾಗಿ ಬಹಿರಂಗಪಡಿಸಿದ AI-ನಿರ್ಮಿತ ಆಟ; Unreal Engine 5 ಗೆ ಸ್ಥಳಾಂತರಿಸಲು ಯೋಜಿಸಲಾಗಿದೆ (ಮಾರ್ಗಸೂಚಿ ಹಂತ 3).",
  "why.fullyDocumentedExample": "ಎಂಜಿನ್‌ನಿಂದ ಆಟದವರೆಗೆ ಏಜೆಂಟಿಕ್ ನಿರ್ಮಾಣದ ಸಂಪೂರ್ಣ ದಾಖಲಿತ ಉದಾಹರಣೆ (ರೆಪೊಸಿಟರಿ, ಟ್ರ್ಯಾಕರ್ ಮತ್ತು ಪ್ರತಿ ಸ್ಥಿರೀಕೃತ ಆವೃತ್ತಿಯನ್ನು ಉಳಿಸಲಾಗಿದೆ), ಮತ್ತು AI ಯ ಲಾಭಗಳು ಅದರಿಂದ ಸ್ಥಾನಪಲ್ಲಟಗೊಂಡ ಜನರಿಗೆ ಹೇಗೆ ಹಣಕಾಸು ಒದಗಿಸಬಹುದು ಎಂಬುದರ ಒಂದು ಮಾರ್ಗದ ಸಣ್ಣ, ಪ್ರಾಯೋಗಿಕ ಪರೀಕ್ಷೆ.",
  "why.fundingGoalAnnounced": "ನಿಧಿ ಗುರಿ: ಇನ್ನೂ ಘೋಷಿಸಬೇಕಿದೆ.",
  "why.kickstarterRoadmapPhase": "Kickstarter (ಮಾರ್ಗಸೂಚಿ ಹಂತ 5) ಸಾರ್ವಜನಿಕ ನಿಧಿ ಸಂಗ್ರಹದ ಮೊದಲ ಸುತ್ತು. ಅದರ ಹಣ AI ಕಾರಣದಿಂದ ಕೆಲಸ ಕಳೆದುಕೊಂಡ ಮೊದಲ ಡೆವಲಪರ್‌ಗಳು ಮತ್ತು ಗ್ರಾಫಿಕ್ ವಿನ್ಯಾಸಕರನ್ನು ನೇಮಿಸಲು ಉದ್ದೇಶಿಸಲಾಗಿದೆ (ಹಂತ 6), ಅವರು ನಂತರ AI-ನಿರ್ಮಿತ ಸಂಪನ್ಮೂಲಗಳನ್ನು ಒಂದೊಂದಾಗಿ ಬದಲಾಯಿಸುತ್ತಾರೆ. <0>ಮೊದಲ ಸುತ್ತು ಪಾತ್ರವಾರು ಯಾವುದಕ್ಕೆ ಹಣ ನೀಡುತ್ತದೆ: ಇನ್ನೂ ಘೋಷಿಸಬೇಕಿದೆ.<\/0>",
  "why.linksContextOnly": "ಲಿಂಕ್‌ಗಳು ಹಿನ್ನೆಲೆಗಾಗಿ ಮಾತ್ರ ಮತ್ತು ಯಾವುದೇ ಅನುಮೋದನೆಯನ್ನು ಸೂಚಿಸುವುದಿಲ್ಲ.",
  "why.n06WhyMatters": "06 · ಇದು ಏಕೆ ಮುಖ್ಯ",
  "why.orion81Tests": "Orion-81 ಆ ಕಲ್ಪನೆಯ ಒಂದು ಸಣ್ಣ ರೂಪವನ್ನು ಪರೀಕ್ಷಿಸುತ್ತದೆ. ಇದು ಯೋಜನೆ ಮಾತ್ರ, ಇನ್ನೂ ಯಾವ ನೇಮಕಾತಿಯೂ ಆಗಿಲ್ಲ.",
  "why.plannedPaidCredited": "ಯೋಜಿತ: ಆದಾಯ ಅನುಮತಿಸಿದಂತೆ, AI-ನಿರ್ಮಿತ ಸಂಪನ್ಮೂಲಗಳನ್ನು ಒಂದೊಂದಾಗಿ ಬದಲಾಯಿಸುವ, ಸಂಭಾವನೆ ಮತ್ತು ಶ್ರೇಯದೊಂದಿಗಿನ ಕೆಲಸ.",
  "why.publishersEngineMakers": "ಪ್ರಕಾಶಕರು ಮತ್ತು ಎಂಜಿನ್ ತಯಾರಕರಿಗಾಗಿ",
  "why.routesThatExist": "Anthropic ನ ಸಾರ್ವಜನಿಕ ಕಾರ್ಯಕ್ರಮಗಳಲ್ಲಿ ಇರುವ ಮಾರ್ಗಗಳಲ್ಲಿ Claude for Startups (ಕ್ರೆಡಿಟ್‌ಗಳು ಮತ್ತು Applied AI ಆಫೀಸ್ ಅವರ್ಸ್) ಮತ್ತು Claude Founder House ಕಾರ್ಯಕ್ರಮಗಳು ಸೇರಿವೆ. AI-ನಿಧಿಯ ಮರು-ಉದ್ಯೋಗವನ್ನು ಅಧ್ಯಯನ ಮಾಡುವ ಸಂಶೋಧಕರಿಗೆ Orion-81 ಕ್ಷೇತ್ರ ತಾಣವೂ ಆಗಬಹುದು. ಯಾವುದೇ ಒಪ್ಪಂದ ಅಥವಾ ಅನುಮೋದನೆ ಅಸ್ತಿತ್ವದಲ್ಲಿಲ್ಲ.",
  "why.studyingAiFunded": "AI-ನಿಧಿಯ ಮರು-ಉದ್ಯೋಗವನ್ನು ಅಧ್ಯಯನ ಮಾಡುತ್ತಿದ್ದೀರಾ? <0>ಸಂಪರ್ಕ ವಿವರಗಳು ಶೀಘ್ರದಲ್ಲೇ ಬರಲಿವೆ.<\/0>",
